-- Record stores
('mm', 'Music Millennium', 'record', 'Buckman / Kerns', -122.6319444, 45.5227167, 4.7, 'Mon–Sat 10 AM–10 PM · Sun 11 AM–9 PM', 'New releases · Massive all-format stock', '🎧', 'Portland''s longest-running record shop — vinyl, CDs, and cassettes across two floors, plus a deep local-artist wall.', null, 'https://www.google.com/maps/place/?q=place_id:ChIJYasibsCglVQR2CKwN4o4b18', current_date),
